  outline = exp(-min(u, width - u) * facing / wpx) + exp(-(tw.y - v) / wpx) + 0.25 * exp(-abs(fract(v * 2.0) - 0.5) / (wpx * 2.0)) * step(0.5, fract(h * 23.0));
