  col = mix(col, mistCol, smoothstep(0.56, 0.44, q.y) * smoothstep(0.4, 0.85, noise(vec2(q.x * 2.3 + u_time * 0.025, q.y * 30.0))) * (0.1 + 0.6 * u_sky.z));

